// file: gemini.js
// Gemini client: use GOOGLE_API_KEY or GOOGLE_OAUTH_BEARER only.
// No hardcoded secrets. This is the control layer for all AI decisions.

const GEMINI_MODEL = process.env.GEMINI_MODEL || 'gemini-pro';

function getGeminiEndpoint() {
  const base = `https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(GEMINI_MODEL)}:generateMessage`;
  if (process.env.GOOGLE_API_KEY) {
    return `${base}?key=${encodeURIComponent(process.env.GOOGLE_API_KEY)}`;
  }
  return base;
}

async function callGemini(payload) {
  const endpoint = getGeminiEndpoint();
  const headers = { 'Content-Type': 'application/json' };
  if (process.env.GOOGLE_OAUTH_BEARER) {
    headers.Authorization = `Bearer ${process.env.GOOGLE_OAUTH_BEARER}`;
  }

  const response = await fetch(endpoint, {
    method: 'POST',
    headers,
    body: JSON.stringify(payload)
  });

  const rawText = await response.text();
  let data = null;

  try {
    data = rawText ? JSON.parse(rawText) : null;
  } catch (err) {
    throw new Error(`Gemini returned invalid JSON: ${rawText.slice(0, 500)}`);
  }

  if (!response.ok) {
    const message = data?.error?.message || rawText || response.statusText;
    const error = new Error(`Gemini API error ${response.status}: ${message}`);
    error.raw = data;
    throw error;
  }

  return data;
}

function extractTextFromGeminiResponse(resp) {
  if (!resp) return '';

  try {
    const candidates = resp?.candidates || resp?.response?.candidates || resp?.outputs || resp?.responses;
    if (Array.isArray(candidates) && candidates.length) {
      const first = candidates[0];
      if (typeof first === 'string') return first;

      if (first?.content?.text) return first.content.text;
      if (first?.message?.content) {
        if (typeof first.message.content === 'string') return first.message.content;
        if (first.message.content?.text) return first.message.content.text;
      }
      if (first?.output_text) return first.output_text;
      if (first?.output && typeof first.output === 'string') return first.output;
      if (first?.content && typeof first.content === 'string') return first.content;
    }

    if (typeof resp?.output_text === 'string') return resp.output_text;
    if (typeof resp?.text === 'string') return resp.text;
    if (typeof resp?.output === 'string') return resp.output;
    if (typeof resp?.message === 'string') return resp.message;
  } catch (_) {
    // fall through to JSON stringify fallback
  }

  try {
    return JSON.stringify(resp);
  } catch (_) {
    return String(resp);
  }
}

async function generateResponse({
  userMessage,
  history = [],
  systemPrompt = '',
  temperature = 0.2,
  maxOutputTokens = 800
}) {
  const messages = [...history, { role: 'user', content: userMessage }];

  const payload = {
    prompt: {
      messages: [
        ...(systemPrompt ? [{ author: 'system', content: systemPrompt }] : []),
        ...messages.map((m) => ({
          author: m.role === 'assistant' ? 'assistant' : 'user',
          content: String(m.content || '')
        }))
      ]
    },
    temperature,
    maxOutputTokens
  };

  const raw = await callGemini(payload);
  const text = extractTextFromGeminiResponse(raw);

  return { raw, text };
}

module.exports = {
  generateResponse
};

