// file: pricing.js
// Locked Bargain Drop Pricing Engine

function getMultiplier(usdCost) {
  if (usdCost < 10) return 3.2;
  if (usdCost <= 15) return 2.8;
  if (usdCost <= 22) return 2.5;
  if (usdCost <= 30) return 2.2;
  if (usdCost <= 60) return 1.9;
  return 1.7;
}

function calculatePrice(usdCost) {
  const cost = Number(usdCost);
  if (isNaN(cost) || cost <= 0) {
    throw new Error('Invalid USD cost provided for pricing calculation.');
  }

  const multiplier = getMultiplier(cost);
  // Formula: ceil(USD_cost * multiplier * 1.4234) - 0.05
  const rawPrice = Math.ceil(cost * multiplier * 1.4234) - 0.05;

  // Ensure precise rounding to two decimals ending in .95
  const finalPrice = Number(rawPrice.toFixed(2));

  return {
    usdCost: cost,
    multiplier,
    price: finalPrice,
    compare_at_price: null
  };
}

module.exports = {
  getMultiplier,
  calculatePrice
};
